#### `src/scheduler/dvfs_controller.fl` - 예상 420줄

Dynamic Voltage and Frequency Scaling의 핵심입니다. Phase 8의 `controlThermalThrottling()` 열 관리 로직과 Phase 9의 `classifyWorkload()` 분류 구조를 활용합니다.

**핵심 구조체 및 열거형:**

```
// DVFS 운영 점 (Operating Point)
struct DVFSPoint {
    frequency_mhz: u32,    // 200 / 400 / 600 / 800 / 1000 / 1200 / 1400 / 1600
    voltage_mv: u32,       // 600 / 700 / 800 / 900 / 1000 / 1100 / 1150 / 1200
    power_mw: f64,         // 해당 OP의 소비 전력 (측정값)
    performance_score: f64, // 0.0-1.0 (상대 성능)
}

// OP별 에너지 효율: performance / power_mw → 최고 효율 OP 탐색

enum DVFSPolicy {
    Performance,     // 최대 주파수 우선
    Balanced,        // 성능/전력 균형
    PowerSave,       // 최소 전력 우선
    Emergency,       // 배터리 위기 (5% 미만) → 최저 OP 고정
}

struct DVFSState {
    current_point: DVFSPoint,
    current_policy: DVFSPolicy,
    transition_count: u64,
    last_transition_ms: u64,
    min_interval_ms: u32,    // 연속 전환 방지: 기본 100ms
}

struct DVFSController {
    operating_points: Vec<DVFSPoint>,   // 8개 OP (200MHz-1600MHz)
    state: DVFSState,
    battery_level: f64,
    thermal_ratio: f64,
}

impl DVFSController {
    fn new() -> DVFSController
        // 8개 OP 초기화: 200/400/600/800/1000/1200/1400/1600 MHz
    fn select_policy(&self, battery_level: f64, load: f64) -> DVFSPolicy
        // battery < 5% → Emergency
        // battery < 20% → PowerSave
        // load > 80% → Performance
        // else → Balanced
    fn target_operating_point(&self, policy: DVFSPolicy, workload_score: f64) -> &DVFSPoint
    fn transition_to(&mut self, target: &DVFSPoint) -> Result<u64, String>
        // 무관용 규칙 3: 전환 완료 < 10ms
        // 반환: 실제 전환 소요 시간 (us)
    fn thermal_scale_factor(&self) -> f64
        // Phase 8 controlThermalThrottling() 그대로:
        // thermal_ratio > 0.90 → 0.5
        // thermal_ratio > 0.80 → 0.8
        // else → 1.0
    fn classify_workload_type(&self, cpu_util: f64, io_rate: f64) -> String
        // Phase 9 classifyWorkload() 구조 동일 (4분류)
    fn update(&mut self, reading: &PowerReading, cpu_util: f64, io_rate: f64)
    fn savings_vs_max_freq(&self) -> f64   // 현재 절감률
}
```

