#### `src/scheduler/sleep_manager.fl` - 예상 380줄

C-state 수면 상태 관리기입니다. `WorkloadConsolidator`와 긴밀히 협력합니다.

**핵심 구조체 및 열거형:**

```
// Linux ACPI C-state 모델
enum CState {
    C0,        // Active: 정상 실행 (전력: 100%)
    C1,        // Halt: CPU 중지, 클럭 유지 (전력: ~70%)
    C3,        // Sleep: 캐시 flush, PLL 중지 (전력: ~20%)
    C6,        // DeepSleep: 코어 전원 차단 (전력: ~2%)
}

impl CState {
    fn power_ratio(&self) -> f64       // C0=1.0, C1=0.70, C3=0.20, C6=0.02
    fn exit_latency_us(&self) -> u32   // C0=0, C1=1, C3=50, C6=200
    fn entry_latency_us(&self) -> u32  // C0=0, C1=1, C3=20, C6=100
    fn min_residency_us(&self) -> u32  // 최소 체류 시간 (C6 진입 가치 기준)
    fn to_string(&self) -> String
}

struct SleepDecision {
    target_state: CState,
    expected_idle_duration_us: u32,  // 예상 유휴 시간
    energy_saving_mj: f64,           // 예상 절감 에너지 (mJ)
    wake_latency_ok: bool,           // wake latency < deadline
}

impl SleepDecision {
    fn is_worth_entering(&self) -> bool
        // energy_saving > entry_cost && wake_latency_ok
}

struct SleepManager {
    current_state: CState,
    state_durations_us: [u64; 4],    // 각 상태 누적 체류 시간
    idle_predictor: IdleTimePredictor,
    wakeup_deadline_us: u32,         // 다음 인터럽트 예상 시간
}

struct IdleTimePredictor {
    history: Vec<u32>,               // 최근 유휴 시간 샘플
    ewma_idle_us: f64,               // 지수 가중 이동 평균
}

impl IdleTimePredictor {
    fn predict_next_idle_us(&self) -> u32
    fn update(&mut self, actual_idle_us: u32)
}

impl SleepManager {
    fn new() -> SleepManager
    fn decide_sleep_state(&self, workload_idle: bool) -> SleepDecision
        // 무관용 규칙 5: sleep 진입 < 5ms
        // idle_us > C6.min_residency → C6
        // idle_us > C3.min_residency → C3
        // idle_us > C1.min_residency → C1
        // else → C0
    fn enter_state(&mut self, state: CState) -> Result<u64, String>
        // 반환: 실제 진입 소요 시간 (us), 검증: < 5000us
    fn exit_to_active(&mut self) -> u64   // C0으로 복귀
    fn efficiency_report(&self) -> SleepEfficiencyReport
}

struct SleepEfficiencyReport {
    c0_ratio: f64,    // Active 비율
    c6_ratio: f64,    // DeepSleep 비율
    avg_power_saving_percent: f64,
}
```

